CREATE TABLE `project_deliverables` (
  `deliverable_id` int NOT NULL AUTO_INCREMENT,
  `milestone_id` int NOT NULL,
  `name` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `file_path` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `status` enum('Pending','Uploaded','Approved','Rejected') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT 'Pending',
  `display_order` int DEFAULT '0',
  `uploaded_at` datetime DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`deliverable_id`),
  KEY `milestone_id` (`milestone_id`),
  CONSTRAINT `project_deliverables_ibfk_1` FOREIGN KEY (`milestone_id`) REFERENCES `project_milestones` (`milestone_id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=148 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
