INSERT INTO `project_milestones` VALUES (1,1,1,'งวดที่ 1','งวดที่ 1 เป็นเงิน 389,566.66 บาท (สามแสนแปดหมื่นเก้าพันห้าร้อยหกสิบหกบาทหกสิบหกสตางค์) จะจ่ายเมื่อผู้รับจ้างได้ดำเนินการบำรุงรักษาระบบสารสนเทศศูนย์ข้อมูลแรงงานแห่งชาติ และการบริหารจัดการระบบวิเคราะห์ข้อมูลขนาดใหญ่ด้านแรงงาน (Labour Big Data Analytics) เพื่อการพัฒนากำลังแรงงานของประเทศ และส่งมอบงาน ระหว่างวันที่ 16 กุมภาพันธ์ - 28 กุมภาพันธ์ 2569 ','2026-02-16','2026-02-28',100,'Completed','2026-06-10 12:59:40',389566.66,'Paid'),(2,1,2,'งวดที่ 2','งวดที่ 2 เป็นเงิน 899,000.00 บาท (แปดแสนเก้าหมื่นเก้าพันบาทถ้วน) จะจ่ายเมื่อผู้รับจ้างได้ดำเนินการบำรุงรักษาระบบสารสนเทศศูนย์ข้อมูลแรงงานแห่งชาติ และการบริหารจัดการระบบวิเคราะห์ข้อมูลขนาดใหญ่ด้านแรงงาน (Labour Big Data Analytics) เพื่อการพัฒนากำลังแรงงานของประเทศ และส่งมอบงาน ระหว่างวันที่ 1 มีนาคม - 31 มีนาคม 2569','2026-03-01','2026-03-31',100,'Completed','2026-06-10 12:59:40',899000.00,'Paid'),(3,1,3,'งวดที่ 3','งวดที่ 3 เป็นเงิน 899,000.00 บาท (แปดแสนเก้าหมื่นเก้าพันบาทถ้วน) จะจ่ายเมื่อผู้รับจ้างได้ดำเนินการบำรุงรักษาระบบสารสนเทศศูนย์ข้อมูลแรงงานแห่งชาติ และการบริหารจัดการระบบวิเคราะห์ข้อมูลขนาดใหญ่ด้านแรงงาน (Labour Big Data Analytics) เพื่อการพัฒนากำลังแรงงานของประเทศ และส่งมอบงาน ระหว่างวันที่ 1 เมษายน - 30 เมษายน 2569','2026-04-01','2026-04-30',0,'Pending','2026-06-10 12:59:40',899000.00,'Pending'),(4,1,4,'งวดที่ 4','งวดที่ 4 เป็นเงิน 899,000.00 บาท (แปดแสนเก้าหมื่นเก้าพันบาทถ้วน) จะจ่ายเมื่อผู้รับจ้างได้ดำเนินการบำรุงรักษาระบบสารสนเทศศูนย์ข้อมูลแรงงานแห่งชาติ และการบริหารจัดการระบบวิเคราะห์ข้อมูลขนาดใหญ่ด้านแรงงาน (Labour Big Data Analytics) เพื่อการพัฒนากำลังแรงงานของประเทศ และส่งมอบงาน ระหว่างวันที่ 1 พฤษภาคม - 31 พฤษภาคม 2569','2026-05-01','2026-05-31',0,'Pending','2026-06-10 12:59:40',899000.00,'Pending'),(5,1,5,'งวดที่ 5','งวดที่ 5 เป็นเงิน 899,000.00 บาท (แปดแสนเก้าหมื่นเก้าพันบาทถ้วน) จะจ่ายเมื่อผู้รับจ้างได้ดำเนินการบำรุงรักษาระบบสารสนเทศศูนย์ข้อมูลแรงงานแห่งชาติ และการบริหารจัดการระบบวิเคราะห์ข้อมูลขนาดใหญ่ด้านแรงงาน (Labour Big Data Analytics) เพื